package app.bean.focus;
public class BrowserAddressTest {public static void main(String[] args){String[] good={"com.android.chrome:id/url_bar","url_field","location_bar_edit_text","location_bar_text_view","mozac_browser_toolbar_url_view","address_bar","url_text","omnibarTextInput","custom_tab_toolbar_url_bar_text","mozac_browser_toolbar_origin_view","toolbar_url"};for(String s:good)if(!BrowserAddress.field(s))throw new AssertionError(s);for(String s:new String[]{"search_box","shorts_recommendation","video_title","navigation_bar"})if(BrowserAddress.field(s))throw new AssertionError(s);if(!UrlRules.isShorts(BrowserAddress.clean("\u200em.youtube.com/shorts/test\u200f")))throw new AssertionError("bidi URL");if(!UrlRules.isShorts(BrowserAddress.better("m.youtube.com","https://m.youtube.com/shorts/full")))throw new AssertionError("full description loses to host");if(BrowserAddress.hasPath("https://youtube.com/"))throw new AssertionError("host mistaken for path");System.out.println("Address-field matching and bidi normalization passed");}}
